io.on('connection', (socket) => {
  socket.on('canvas:draw_shape', async ({ whiteboardId, shapeData }) => {
    const board = await CanvasModel.findOne({ _id: whiteboardId, 'collaborators.userId': socket.data.userId, 'collaborators.canEdit': true });
    if (!board) {
      return socket.emit('error', { message: 'Insufficient edit permissions for this canvas' });
    }
    board.shapes.push(shapeData);
    await board.save();
    io.to(`canvas:${whiteboardId}`).emit('canvas:shape_added', shapeData);
  });
});
